const {candidates, editorial_source, collection_started_at} = $json;
const categories = {"politica":1,"economia":2,"cidades":3,"esporte":4,"justica":5,"mundo":6,"tecnologia":7,"piaui":8,"sao-paulo":9,"rio-de-janeiro":10,"ceara":11,"cultura":12,"geral":13,"saude":14};
if (typeof editorial_source !== 'string' || !Array.isArray(candidates) || candidates.length < 1 || candidates.length > 10 || candidates.some(c => !c || !Object.hasOwn(categories, c.editoria))) throw Error('Lote de coleta inválido.');
return {json:{candidates, editorial_source, collection_started_at, publish_by_briefing:$json.publish_by_briefing===true}};

const lot = $('Conferir candidatas').item.json;
if ($json.success !== true || !Array.isArray($json.data)) throw Error('Cobertura do CMS indisponível.');
const categories = {"politica":1,"economia":2,"cidades":3,"esporte":4,"justica":5,"mundo":6,"tecnologia":7,"piaui":8,"sao-paulo":9,"rio-de-janeiro":10,"ceara":11,"cultura":12,"geral":13,"saude":14};
const selected = new Set(lot.candidates.map(x => categories[x.editoria]));
const cutoff = Date.parse(lot.collection_started_at);
const recent = Number.isFinite(cutoff) ? $json.data.filter(p => !(Date.parse(p.published_at) > cutoff)) : $json.data;
const relevant = recent.filter(p => selected.has(p.category_id));
const other = recent.filter(p => !selected.has(p.category_id));
const coverage = [...relevant, ...other].slice(0,30).map(p => ({id:p.id, category_id:p.category_id, title:p.title, excerpt:p.excerpt, original_link:p.original_link, published_at:p.published_at}));
return {json:{...lot,coverage,queue:[],stage_for_publication:lot.publish_by_briefing,publish_enabled:lot.publish_by_briefing}};
